package e2e
import("encoding/json";"fmt";"net/http";"os";"testing";"time")
func TestMediaControlShareMetadataE2E(t *testing.T){a,ctrl:=os.Getenv("MEDIA_AUTH_ADDR"),os.Getenv("MEDIA_CONTROL_ADDR");if a==""||ctrl==""{t.Skip("MEDIA_AUTH_ADDR and MEDIA_CONTROL_ADDR are required")};c:=httpClient(t);login(t,c,a,envOr("MEDIA_AUTH_E2E_USER","smoke"),envOr("MEDIA_AUTH_E2E_PASS","smoke123"));s,b:=doJSON(t,c,http.MethodPost,ctrl+"/api/v1/workspaces",map[string]string{"name":fmt.Sprintf("share-%d",time.Now().UnixNano()),"agent_type":"codex"});if s!=http.StatusCreated{t.Fatalf("workspace: %d %s",s,b)};var w struct{ID string};json.Unmarshal(b,&w);s,b=doJSON(t,c,http.MethodPost,ctrl+"/api/v1/share-metadata",map[string]string{"workspace_id":w.ID,"resource_type":"prompt","resource_id":"prompt-1"});if s!=http.StatusCreated{t.Fatalf("share: %d %s",s,b)};var sh struct{ID,Status string};json.Unmarshal(b,&sh);if sh.ID==""||sh.Status!="active"{t.Fatalf("unexpected share: %+v",sh)};s,b=doJSON(t,c,http.MethodGet,ctrl+"/api/v1/share-metadata?workspace_id="+w.ID+"&resource_type=prompt&resource_id=prompt-1",nil);if s!=http.StatusOK||!jsonContains(b,`"status":"active"`){t.Fatalf("list shares: %d %s",s,b)};s,b=doJSON(t,c,http.MethodPost,ctrl+"/api/v1/share-metadata/"+sh.ID+"/revoke",map[string]any{});if s!=http.StatusOK||!jsonContains(b,`"status":"revoked"`){t.Fatalf("revoke share: %d %s",s,b)}}
